import React, { useState, useRef, useEffect } from 'react';
import './Calendrier.css';
import AjouterTrajet from './AjouterTrajet';

const Calendrier = () => {
  const [activeTab, setActiveTab] = useState("Semaine");
  const [selectedView, setSelectedView] = useState("Semaine");
  const [selectedPerson, setSelectedPerson] = useState("Tous");
  const [filterPerson, setFilterPerson] = useState("Tous"); // Nouveau state pour le filtre
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showDatePicker, setShowDatePicker] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  
  const datePickerRef = useRef(null);

  // Fermer le datepicker quand on clique en dehors
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (datePickerRef.current && !datePickerRef.current.contains(event.target)) {
        setShowDatePicker(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Onglets principaux
  const tabs = ["Aujourd'hui", "Personne", "Semaine"];

  // Données pour différentes vues
  const views = ["Jour", "Semaine", "Mois", "Année"];
  
  // Données des personnes
  const personnesList = [
    { id: 1, name: 'Loïc', role: 'Chauffeur', statut: 'Disponible', trajets: 12 },
    { id: 2, name: 'Paul', role: 'Chauffeur', statut: 'En trajet', trajets: 8 },
    { id: 3, name: 'Jose', role: 'Coordinateur', statut: 'Disponible', trajets: 15 },
    { id: 4, name: 'Jean', role: 'Chauffeur', statut: 'Congés', trajets: 10 },
    { id: 5, name: 'Jase', role: 'Assistant', statut: 'Disponible', trajets: 6 }
  ];

  // Données du planning
  const joursSemaine = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];
  const timeSlots = ['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00'];
  
  const planningData = {
    'Lundi': ['Loïc', 'Paul'],
    'Mardi': ['Jose', 'Jean'],
    'Mercredi': ['Loïc', 'Paul'],
    'Jeudi': ['Jose', 'Jean'],
    'Vendredi': ['Loïc', 'Paul'],
    'Samedi': ['Jase', 'Jean'],
    'Dimanche': ['Loïc', 'Paul']
  };

  // Données complètes des trajets (avec filtrage)
  const trajetsData = [
    { id: 1, heure: '08:30', client: 'Hôpital Central', personne: 'Loïc', statut: 'En cours', date: new Date() },
    { id: 2, heure: '10:15', client: 'Clinique Nord', personne: 'Marie', statut: 'À venir', date: new Date() },
    { id: 3, heure: '14:00', client: 'Centre Médical', personne: 'Paul', statut: 'À venir', date: new Date() },
    { id: 4, heure: '16:45', client: 'Résidence Soleil', personne: 'Jean', statut: 'Planifié', date: new Date() },
    { id: 5, heure: '09:00', client: 'Clinique Sud', personne: 'Loïc', statut: 'Terminé', date: new Date(Date.now() - 86400000) },
    { id: 6, heure: '11:30', client: 'Hôpital Est', personne: 'Jose', statut: 'En cours', date: new Date(Date.now() - 86400000) },
    { id: 7, heure: '13:45', client: 'Centre de Rééducation', personne: 'Paul', statut: 'À venir', date: new Date(Date.now() + 86400000) },
    { id: 8, heure: '15:20', client: 'Maison de Retraite', personne: 'Jean', statut: 'Planifié', date: new Date(Date.now() + 86400000) }
  ];

  // Formatter la date
  const formatDate = (date) => {
    return date.toLocaleDateString('fr-FR', { 
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
  };

  const formatShortDate = (date) => {
    return date.toLocaleDateString('fr-FR', {
      day: 'numeric',
      month: 'short'
    });
  };

  const formatMonthYear = (date) => {
    return date.toLocaleDateString('fr-FR', {
      month: 'long',
      year: 'numeric'
    });
  };

  // Navigation des dates
  const handlePrevDay = () => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() - 1);
    setCurrentDate(newDate);
  };

  const handleNextDay = () => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() + 1);
    setCurrentDate(newDate);
  };

  const handleToday = () => {
    const today = new Date();
    setCurrentDate(today);
    setSelectedMonth(today);
  };

  const handleSelectDate = (date) => {
    setCurrentDate(date);
    setShowDatePicker(false);
  };

  const handlePrevMonth = () => {
    const newMonth = new Date(selectedMonth);
    newMonth.setMonth(newMonth.getMonth() - 1);
    setSelectedMonth(newMonth);
  };

  const handleNextMonth = () => {
    const newMonth = new Date(selectedMonth);
    newMonth.setMonth(newMonth.getMonth() + 1);
    setSelectedMonth(newMonth);
  };

  // Générer les jours du mois pour le calendrier
  const generateCalendarDays = () => {
    const year = selectedMonth.getFullYear();
    const month = selectedMonth.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const daysInMonth = lastDay.getDate();
    const startingDay = firstDay.getDay();
    
    const days = [];
    
    // Jours vides au début
    for (let i = 0; i < startingDay; i++) {
      days.push(<div key={`empty-${i}`} className="calendar-day empty"></div>);
    }
    
    // Jours du mois
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      const isToday = isSameDay(date, new Date());
      const isSelected = isSameDay(date, currentDate);
      const hasTrajets = trajetsData.some(trajet => isSameDay(trajet.date, date));
      
      days.push(
        <div 
          key={day}
          className={`calendar-day ${isToday ? 'today' : ''} ${isSelected ? 'selected' : ''} ${hasTrajets ? 'has-trajets' : ''}`}
          onClick={() => handleSelectDate(date)}
        >
          {day}
          {hasTrajets && <div className="trajets-indicator">•</div>}
        </div>
      );
    }
    
    return days;
  };

  const isSameDay = (date1, date2) => {
    if (!date1 || !date2) return false;
    return date1.getDate() === date2.getDate() &&
           date1.getMonth() === date2.getMonth() &&
           date1.getFullYear() === date2.getFullYear();
  };

  // Filtrer les trajets pour la date sélectionnée
  const getFilteredTrajets = () => {
    return trajetsData.filter(trajet => {
      const dateMatch = isSameDay(trajet.date, currentDate);
      const personMatch = filterPerson === 'Tous' || trajet.personne === filterPerson;
      return dateMatch && personMatch;
    });
  };

  // Compter les trajets par statut
  const getTrajetsStats = () => {
    const filteredTrajets = getFilteredTrajets();
    const total = filteredTrajets.length;
    const enCours = filteredTrajets.filter(t => t.statut === 'En cours').length;
    const aVenir = filteredTrajets.filter(t => t.statut === 'À venir').length;
    const planifies = filteredTrajets.filter(t => t.statut === 'Planifié').length;
    
    return { total, enCours, aVenir, planifies };
  };

  const handleSaveTrajet = (trajetData) => {
    console.log('Trajet enregistré:', trajetData);
    setShowModal(false);
  };

  // Rendu du contenu selon l'onglet actif
  const renderContent = () => {
    switch(activeTab) {
      case "Aujourd'hui":
        const filteredTrajets = getFilteredTrajets();
        const stats = getTrajetsStats();
        
        return (
          <div className="content-today">
            {/* Header avec dropdown datepicker et filtre */}
            <div className="today-header">
              <div className="date-dropdown-container" ref={datePickerRef}>
                <button 
                  className="date-dropdown-btn"
                  onClick={() => setShowDatePicker(!showDatePicker)}
                >
                  <div className="dropdown-selected-date">
                    {formatDate(currentDate)}
                  </div>
                  <div className="dropdown-arrow">
                    {showDatePicker ? '▲' : '▼'}
                  </div>
                </button>
                
                {showDatePicker && (
                  <div className="date-dropdown-content">
                    <div className="dropdown-calendar">
                      <div className="dropdown-calendar-header">
                        <button className="month-nav-btn" onClick={handlePrevMonth}>‹</button>
                        <div className="dropdown-current-month">
                          {formatMonthYear(selectedMonth)}
                        </div>
                        <button className="month-nav-btn" onClick={handleNextMonth}>›</button>
                      </div>
                      
                      <div className="dropdown-weekdays">
                        <div>Lun</div>
                        <div>Mar</div>
                        <div>Mer</div>
                        <div>Jeu</div>
                        <div>Ven</div>
                        <div>Sam</div>
                        <div>Dim</div>
                      </div>
                      
                      <div className="dropdown-calendar-days">
                        {generateCalendarDays()}
                      </div>
                      
                      <div className="dropdown-actions">
                        <button className="today-action-btn" onClick={handleToday}>
                          Aujourd'hui
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>

              {/* Navigation et filtre */}
              <div className="date-filters">
                <div className="date-navigation">
                  <button className="nav-button" onClick={handlePrevDay}>‹</button>
                  <button className="nav-button today-btn" onClick={handleToday}>Aujourd'hui</button>
                  <button className="nav-button" onClick={handleNextDay}>›</button>
                </div>
                
                <div className="person-filter-today">
                  <select 
                    className="person-filter-select"
                    value={filterPerson}
                    onChange={(e) => setFilterPerson(e.target.value)}
                  >
                    <option value="Tous">Toutes les personnes</option>
                    {personnesList.map(p => (
                      <option key={p.id} value={p.name}>{p.name}</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* Statistiques avec filtrage */}
            <div className="today-stats">
              <div className="stat-card">
                <div className="stat-number">{stats.total}</div>
                <div className="stat-label">Trajets</div>
                <div className="stat-detail">
                  {filterPerson !== 'Tous' ? `pour ${filterPerson}` : 'au total'}
                </div>
              </div>
              <div className="stat-card">
                <div className="stat-number">{stats.enCours}</div>
                <div className="stat-label">En cours</div>
                <div className="stat-detail">
                  {stats.enCours > 0 ? `${stats.enCours}/${stats.total}` : 'Aucun'}
                </div>
              </div>
              <div className="stat-card">
                <div className="stat-number">{stats.aVenir + stats.planifies}</div>
                <div className="stat-label">À venir</div>
                <div className="stat-detail">
                  {stats.aVenir} à venir, {stats.planifies} planifiés
                </div>
              </div>
            </div>

            {/* Liste des trajets filtrés */}
            <div className="today-trajets">
              <div className="trajets-header">
                <h3>Planning du {formatDate(currentDate)}</h3>
                {filterPerson !== 'Tous' && (
                  <div className="filter-info">
                    Filtre : <span className="filter-person">{filterPerson}</span>
                    <button 
                      className="clear-filter-btn"
                      onClick={() => setFilterPerson('Tous')}
                    >
                      ×
                    </button>
                  </div>
                )}
              </div>
              
              <div className="trajets-list">
                {filteredTrajets.length > 0 ? (
                  filteredTrajets.map(trajet => (
                    <div key={trajet.id} className="trajet-item">
                      <div className="trajet-time">{trajet.heure}</div>
                      <div className="trajet-info">
                        <div className="trajet-client">{trajet.client}</div>
                        <div className="trajet-person">avec {trajet.personne}</div>
                      </div>
                      <div className="trajet-actions">
                        <div className={`trajet-statut ${trajet.statut.toLowerCase().replace(' ', '-').replace('é', 'e')}`}>
                          {trajet.statut}
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="no-trajets">
                    {filterPerson === 'Tous' 
                      ? `Aucun trajet programmé pour le ${formatDate(currentDate)}`
                      : `Aucun trajet pour ${filterPerson} le ${formatDate(currentDate)}`
                    }
                  </div>
                )}
              </div>
            </div>
          </div>
        );

      case "Personne":
        return (
          <div className="content-person">
            <div className="person-filter-header">
              <h2>Équipe & Planning</h2>
              <select 
                className="person-select-large"
                value={selectedPerson}
                onChange={(e) => setSelectedPerson(e.target.value)}
              >
                <option value="Tous">Toute l'équipe</option>
                {personnesList.map(p => (
                  <option key={p.id} value={p.name}>{p.name}</option>
                ))}
              </select>
            </div>

            <div className="person-grid">
              <div className="person-list">
                <h3>Membres de l'équipe</h3>
                {personnesList.map(person => (
                  <div 
                    key={person.id} 
                    className={`person-card ${selectedPerson === person.name || selectedPerson === 'Tous' ? 'selected' : ''}`}
                    onClick={() => setSelectedPerson(person.name)}
                  >
                    <div className="person-avatar">
                      {person.name.charAt(0)}
                    </div>
                    <div className="person-details">
                      <div className="person-name">{person.name}</div>
                      <div className="person-role">{person.role}</div>
                    </div>
                    <div className="person-stats">
                      <div className="person-trajets">{person.trajets} trajets</div>
                      <div className={`person-status ${person.statut.toLowerCase().replace('é', 'e')}`}>
                        {person.statut}
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="person-planning">
                <h3>
                  {selectedPerson === 'Tous' ? 'Planning de l\'équipe' : `Planning de ${selectedPerson}`}
                </h3>
                <div className="mini-calendar">
                  <div className="mini-days">
                    {['L', 'M', 'M', 'J', 'V', 'S', 'D'].map((day, index) => (
                      <div key={index} className="mini-day">
                        {day}
                      </div>
                    ))}
                  </div>
                  <div className="mini-slots">
                    {timeSlots.slice(0, 6).map(time => (
                      <div key={time} className="mini-time-slot">
                        <div className="mini-time">{time}</div>
                        <div className="mini-activity">
                          {selectedPerson === 'Loïc' && time === '09:00' && '✓'}
                          {selectedPerson === 'Paul' && time === '10:00' && '✓'}
                          {selectedPerson === 'Jose' && time === '11:00' && '✓'}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );

      case "Semaine":
        return (
          <div className="content-week">
            <div className="week-header">
              <h2>Planning de la semaine</h2>
              <div className="view-selector">
                {views.map(view => (
                  <button
                    key={view}
                    className={`view-button ${selectedView === view ? 'active' : ''}`}
                    onClick={() => setSelectedView(view)}
                  >
                    {view}
                  </button>
                ))}
              </div>
            </div>

            <div className="week-navigation">
              <button className="nav-button" onClick={handlePrevDay}>‹ Semaine précédente</button>
              <div className="current-week">
                Semaine du {formatShortDate(getStartOfWeek(currentDate))} au {formatShortDate(getEndOfWeek(currentDate))}
              </div>
              <button className="nav-button" onClick={handleNextDay}>Semaine suivante ›</button>
            </div>

            <div className="calendrier-grid">
              <div className="days-header">
                <div className="day-header"></div>
                {joursSemaine.map(day => (
                  <div key={day} className="day-header">{day}</div>
                ))}
              </div>

              <div className="time-slots">
                {timeSlots.map((time, timeIndex) => (
                  <div key={time} className="time-row">
                    <div className="time-label">{time}</div>
                    {joursSemaine.map(day => (
                      <div key={`${day}-${time}`} className="day-cell">
                        {planningData[day] && timeIndex === 1 && (
                          planningData[day].map((person, index) => (
                            <div 
                              key={`${day}-${person}-${index}`} 
                              className="person-item"
                              style={{ 
                                backgroundColor: getPersonColor(person)
                              }}
                            >
                              {person}
                            </div>
                          ))
                        )}
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            </div>
          </div>
        );

      default:
        return (
          <div className="content-default">
            <p>Sélectionnez une vue pour afficher le contenu</p>
          </div>
        );
    }
  };

  // Fonctions utilitaires
  const getPersonColor = (name) => {
    return {
      'Loïc': '#e3f2fd',
      'Paul': '#f3e5f5', 
      'Jose': '#e8f5e9',
      'Jean': '#fff3e0',
      'Jase': '#fce4ec'
    }[name] || '#e3f2fd';
  };

  const getStartOfWeek = (date) => {
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(date.setDate(diff));
  };

  const getEndOfWeek = (date) => {
    const start = getStartOfWeek(date);
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return end;
  };

  return (
    <div className="page-content full-width">
      <div className="calendrier-header">
        <div className="tabs-container">
          {tabs.map(tab => (
            <button
              key={tab}
              className={`tab-button ${activeTab === tab ? 'active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </button>
          ))}
        </div>

        <button 
          className="add-trajet-btn"
          onClick={() => setShowModal(true)}
        >
          <span>+</span> Ajouter un trajet
        </button>
      </div>

      <div className="calendrier-content">
        {renderContent()}
      </div>

      <AjouterTrajet 
        isOpen={showModal}
        onClose={() => setShowModal(false)}
        onSave={handleSaveTrajet}
      />
    </div>
  );
};

export default Calendrier;
